/* ---------- Onda 4b: Área técnica: Mapa, Digitação, Conferência, Recoletas, Soroteca, Microbiologia, Aparelhos, Controle de qualidade ---------- */

/* ===== Mapa de trabalho (aba Mapa: D11, gerado do cadastro, complementar, controles, reimpressão) ===== */
let MP_BANC='BIO';
const MAPA_POS=[{n:1,cod:'10-00018241-01-02',pac:'Raimundo N. S.',ex:'K',sit:'aparelho',urg:true},{n:2,cod:'10-00018241-01-02',pac:'Raimundo N. S.',ex:'CREA',sit:'aparelho',urg:true},{n:3,cod:'CQ-GLI-N1-0929',pac:'Controle nível 1',ex:'GLI',sit:'controle'},{n:4,cod:'10-00018233-01-02',pac:'Maria H. S.',ex:'GLI',sit:'recebido'},{n:5,cod:'10-00018233-01-02',pac:'Maria H. S.',ex:'K',sit:'recebido',rep:true},{n:6,cod:'10-00018262-01-01',pac:'Cícero R.',ex:'K',sit:'fila',urg:true},{n:7,cod:'10-00018255-01-01',pac:'Francisco C.',ex:'HBA1C',sit:'fila'},{n:8,cod:'14-00004502-01-01',pac:'Marcos V. R.',ex:'CREA',sit:'cancelada'}];
const SIT_POS={fila:['Na fila','neutral'],mapa:['No mapa','info'],aparelho:['No aparelho','acc'],recebido:['Resultado recebido','ok'],digitado:['Digitado','ok'],controle:['Controle','warn'],cancelada:['Cancelada','err']};
VIEWS.mapa=()=>`${pageHead('Área técnica','Mapa de trabalho','Lista de trabalho da bancada no dia, montada pelo sistema a partir do cadastro: urgentes no topo, agrupada por exame, com os controles nas posições da regra. Dados de exemplo.',`${rulesBtn('Mapa de trabalho')}<button class="btn sec" onclick="mpImprimir()" ${tipAttr('Imprimir','Opcional: recorte (bancadas, paciente, exame, só urgências...), modelo de aparência e visualização antes.')}>${I.print} Imprimir</button><button class="btn sec" onclick="toast('Mapa complementar 23-1 gerado com 2 amostras que chegaram depois')" ${tipAttr('Mapa complementar','Pega o que chegou depois do mapa do dia; ganha o número do mapa + sufixo (ex.: 23-1).')}>Complementar</button><button class="btn" onclick="mpGerar()" ${tipAttr('Gerar mapa','Pega tudo pendente da bancada agora. Em bancada interfaceada, envia a worklist ao aparelho.')}>Gerar mapa</button>`)}
<div class="row"><select class="in" style="width:auto" onchange="MP_BANC=this.value;reView()" aria-label="Bancada">${BANCADAS.filter(b=>b.ativo&&b.c!=='APO').map(b=>`<option value="${b.c}" ${MP_BANC===b.c?'selected':''}>${b.n}${b.ap?' · '+b.ap:' · manual'}</option>`).join('')}</select><span class="tl">Mapa nº 23 · gerado às 08:40 por Tiago · período: hoje</span><button class="chip" onclick="toast('Mapas emitidos: 23 (08:40), 22 (ontem), 21...')" ${tipAttr('Mapas emitidos','Lista paginada por número, bancada e data; reimpressão só com exames ainda sem resultado.')}>Mapas emitidos</button></div>
<div class="grid" style="grid-template-columns:2fr 1fr">
<div class="card at-card"><h3>${BANCADAS.find(b=>b.c===MP_BANC).n} · hoje ${info('Cada posição mostra a situação do tubo e abre a digitação direto. O código do exame no mapa também abre a digitação ao ser lido.')}</h3><div class="sub">${MAPA_POS.length} posições · 3 urgentes · 1 repetição · 1 controle</div>
<div class="stack">${MAPA_POS.map(p=>{const [st,sc]=SIT_POS[p.sit];return `<div class="pos ${p.urg?'urg':''} ${p.rep?'rep':''}" style="${p.sit==='cancelada'?'opacity:.5;text-decoration:line-through':''}" onclick="${p.sit==='controle'?`toast('Controle digitado junto com os pacientes (P4)')`:p.sit==='cancelada'?`toast('Atendimento cancelado: posição riscada até regenerar','warn')`:`location.hash='#digitacao'`}" ${tipAttr('Posição '+p.n,'Clique para abrir a digitação deste exame.')}><span class="n">${String(p.n).padStart(2,'0')}</span><span><span class="mono">${p.cod}</span> <span class="badge ${sc}" style="margin-left:6px">${st}</span>${p.urg?' <span class="badge err pisca">URGENTE</span>':''}${p.rep?' <span class="badge warn">repetição</span>':''}<small class="tl" style="display:block">${esc(p.pac)} · <b>${p.ex}</b>${EX[p.ex]?' · '+EX[p.ex].n:''}</small></span><span class="row" style="gap:6px">${p.sit==='fila'||p.sit==='mapa'?`<button class="btn sm ghost" onclick="event.stopPropagation();modalOk('Devolver à fila','<div class=\\'field\\'><label>Motivo</label><select class=\\'in\\'><option>Tubo não encontrado</option><option>Volume insuficiente</option><option>Aguardar reagente</option></select></div>','Devolver','toast(\\'Posição devolvida à fila com motivo\\')')">Devolver</button>${info('Devolver à fila tira o tubo deste mapa com um motivo (tubo não encontrado, volume, reagente); ele volta a aparecer no próximo mapa ou complementar, sem perder o pedido.')}`:''}</span></div>`}).join('')}</div>
${piada(22,{tecnico:'O mapa foi gerado sozinho. O café, não. Prioridades do sistema.',dr:'Repetição na posição 5: o potássio não gostou do primeiro resultado e pediu segunda opinião.',todos:'Mapa de trabalho: a única lista do laboratório em que ficar "na fila" é normal.'})}</div>
<div class="stack"><div class="card"><h3>Fila "resultado sem amostra" ${info('Resultado do aparelho que não casou com nenhum tubo nem controle. O técnico liga ao pedido ou descarta com motivo; alerta ao supervisor após 1 hora.')}</h3><div class="sub">1 pendente · chegou 08:52</div><div class="pos"><span class="n">?</span><span><span class="mono">10-00018299-01-01</span><small class="tl" style="display:block">Analisador A · glicose 94 mg/dL</small></span><span class="row" style="gap:6px"><button class="btn sm sec" onclick="toast('Ligado ao pedido 10-00018299 (digitado à mão, registrado)')">Ligar</button><button class="btn sm ghost" onclick="toast('Descartado com motivo','warn')">Descartar</button></span></div></div>
<div class="card"><h3>Fechamento da rodada ${info('Não segura resultado: mostra o que rodou, o que falta e a fila sem amostra; fecha e registra no dashboard.')}</h3><div class="mini">${miniKpi('Rodou','5','de 8')}${miniKpi('Faltam','2','posições 6 e 7','warn')}${miniKpi('Sem amostra','1','','err')}</div><button class="btn sec" style="margin-top:10px" onclick="toast('Rodada fechada por Tiago às 09:01, registrada no dashboard da área técnica')">Fechar rodada</button></div></div>
</div>`;
function mpGerar(){retorno('ok','Mapa 24 gerado','8 posições, urgentes no topo, controle do nível 1 na posição 3. Worklist enviada ao Analisador A em 2 s.')}
function mpImprimir(){openModal(`${mh('Imprimir mapa')}<div class="mb"><div class="formgrid"><div class="field"><label>Recorte</label><select class="in"><option>Esta bancada, tudo</option><option>Só urgências</option><option>Só repetições</option><option>Só sem resultado</option><option>Só complementar desde a última impressão</option><option>Um paciente</option><option>Um protocolo</option></select></div><div class="field"><label>Modelo ${info('O conteúdo vem do cadastro (D11); o modelo define só a aparência: linha, bloco ou página por amostra.')}</label><select class="in"><option>Linha por amostra (padrão da bancada)</option><option>Bloco por amostra</option><option>Página por amostra</option></select></div></div><label class="check"><input type="checkbox">Valor de referência calculado para o paciente (opcional)</label><div class="alert info"><span>Reimpressão traz só exames ainda sem resultado digitado e sai marcada como reimpressão.</span></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn sec" onclick="toast('Visualização do mapa aberta')">Visualizar</button><button class="btn" onclick="closeModal();toast('Mapa 23 impresso com os filtros registrados')">Imprimir</button></div>`)}
GUIDES.mapa=['Escolha a bancada e gere o mapa: ele pega tudo que está pendente agora, com urgentes no topo e os controles no lugar da regra.','Cada posição abre a digitação; ler o código do exame no papel abre o mesmo campo.','O que chegar depois entra no complementar. Imprimir é opcional.'];
REGRAS['Mapa de trabalho']={aba:'Mapa de trabalho',itens:[['D11','O sistema monta o mapa do cadastro: amostras recebidas, com exames sem resultado; cada exame diz se ocupa linha ou bloco; componentes marcados ganham espaço para anotar.'],['Numeração','Número único no laboratório com código de barras; complementar = número do dia + sufixo (15-1). Cada exame tem código próprio que abre a digitação.'],['Aparelho','Gerar mapa de bancada interfaceada envia a worklist; resultado devolvido deixa a posição verde, aguardando conferência; tubo fora do mapa vai à fila "resultado sem amostra".'],['Controles','Nas posições da regra da bancada (início de rodada ou a cada N), com níveis cadastrados, digitados junto com os pacientes (P4).'],['Repetição','Exame recusado pelo Dr. volta ao próximo mapa marcado como repetição, nova posição ligada à original, guardando os dois valores.'],['Impressão','Recortes combináveis, modelo por bancada, visualização antes; reimpressão só do que ainda não tem resultado e marcada.']]};

/* ===== Digitação (aba Digitação e conferência: leitura contínua, campos por tipo, valor absurdo, salvar parcial) =====
   29/10, noite: campo de bipagem no topo (tubo ou unidade + protocolo), mais filtros, F2 abre o histórico do paciente,
   todas as funções da liberação menos assinar; valor fora da faixa fica em destaque enquanto digita. */
let DG_FILTRO='pendente';
const DIGIT=[{cod:'10-00018233-01-02',pac:'Maria Helena Souza',prot:'10-00018233',ex:'GLI',sit:'pendente',urg:false,prazo:'16:00',banc:'Bioquímica'},{cod:'10-00018233-01-02',pac:'Maria Helena Souza',prot:'10-00018233',ex:'K',sit:'recusado',motivo:'Repetir exame · hemólise visual',urg:false,prazo:'16:00',banc:'Bioquímica'},{cod:'10-00018262-01-01',pac:'Cícero Romão',prot:'10-00018262',ex:'K',sit:'pendente',urg:true,prazo:'09:40',banc:'Bioquímica'},{cod:'10-00018255-01-01',pac:'Francisco das Chagas',prot:'10-00018255',ex:'HBA1C',sit:'pendente',urg:false,prazo:'16:00',banc:'Bioquímica'},{cod:'14-00004503-04-01',pac:'Joana Darc Pereira',prot:'14-00004503',ex:'EAS',sit:'em',urg:false,prazo:'16:00',banc:'Urinálise'},{cod:'10-00018250-01-01',pac:'Larissa Monteiro',prot:'10-00018250',ex:'TSH',sit:'pendente',urg:false,prazo:'amanhã 16:00',banc:'Hormônios'}];
const urgPrimeiro=(a,b)=>(b.urg?1:0)-(a.urg?1:0);
function dgLista(){const f=FILTROS.dg||{};return DIGIT.filter(d=>(DG_FILTRO==='todos'||(DG_FILTRO==='pendente'?d.sit!=='recusado':d.sit===DG_FILTRO))&&(!f.bancada||d.banc===f.bancada)&&(!f.exame||d.ex===f.exame)&&(!f.unidade||d.cod.startsWith(f.unidade+'-'))&&(!f.urgencia||(f.urgencia==='urg')===!!d.urg)).sort(urgPrimeiro)}
VIEWS.digitacao=()=>{const l=dgLista();
 return `${pageHead('Área técnica','Digitação','Resultados dos exames manuais, por bancada: urgências primeiro, depois por prazo. Dados de exemplo.',`${rulesBtn('Digitação')}<button class="btn sec" onclick="dgLeitura()" ${tipAttr('Leitura contínua','Uma tela por leitura: bipe o tubo e aparecem só os exames manuais pendentes dele na bancada.')}>Leitura contínua</button><button class="btn" onclick="dgAbrir(0)" ${tipAttr('Digitar','Abre o primeiro pendente da fila, com urgências na frente.')}>Digitar próximo</button>`)}
<div class="card at-card" style="padding:16px 20px"><div class="row" style="align-items:flex-end;gap:12px"><div class="field" style="flex:1 1 320px;margin:0"><label>Bipe o tubo ou digite unidade + protocolo ${info('Tubo (14 dígitos): abre só os exames daquele tubo. Unidade + protocolo (ex.: 10-18241): abre o paciente com todos os exames dele, sem separar por bancada ou tipo de amostra. Registra e já fica pronto para o próximo.')}</label><div class="inwrap">${LUPA}<input class="in" id="dgBip" placeholder="Ex.: 10-18241 ou 10-00018241-01-02" autofocus></div></div><span class="tl" style="padding-bottom:10px">F2 abre o histórico do paciente em qualquer janela desta tela</span></div><div class="bip-log" id="dgLog"></div></div>
<div class="filters" style="margin-bottom:8px">${[['pendente','Pendentes'],['em','Em digitação'],['recusado','Recusados pelo Dr.'],['todos','Todos']].map(([k,t])=>chip(t,DG_FILTRO===k,`DG_FILTRO='${k}';reView()`)).join('')}</div>
${filtroBarra({id:'dg',periodo:true,bancada:true,exame:true,unidade:true,urgencia:true,onchange:'reView()'})}
${tabela(['Tubo','Paciente','Exame','Prazo','Situação',''],l.map((d,i)=>`<tr style="cursor:pointer" onclick="dgAbrir(${DIGIT.indexOf(d)})">${td('Tubo',`<span class="mono">${d.cod}</span>${d.urg?'<br><span class="badge err pisca urg2">URGENTE</span>':''}`)}${td('Paciente',`<a href="#" onclick="event.preventDefault();event.stopPropagation();historicoPaciente('${d.prot}','digitacao')" ${tipAttr('Paciente','Abre o histórico do paciente com todos os exames (F2).')}>${esc(d.pac)}</a>`)}${td('Exame',`<b>${d.ex}</b><small class="tl exame2" title="${EX[d.ex].n}">${EX[d.ex].n}</small>`)}${td('Prazo',prazoTag(d.prazo))}${td('Situação',d.sit==='recusado'?`<span class="badge err">Recusado</span> <small class="tl">${d.motivo}</small>`:d.sit==='em'?'<span class="badge info">Em digitação</span>':'<span class="badge neutral">Pendente</span>')}${td('',`<button class="btn sm sec" onclick="event.stopPropagation();dgAbrir(${DIGIT.indexOf(d)})">${d.sit==='recusado'?'Corrigir':'Digitar'}</button>`)}</tr>`),'Nada pendente com estes filtros')}
${piada(23,{tecnico:'Valor absurdo pede nova digitação. Não é desconfiança, é só o sistema sendo o colega chato que confere.',todos:'Digitar glicose 9400 mg/dL não é diabetes, é o dedo que escorregou. O sistema pergunta de novo, com carinho.'})}`};
/* Faixas de referência de exemplo, para destacar o que está fora */
const FAIXA={K:[3.5,5.1,'mmol/L'],GLI:[70,99,'mg/dL'],HBA1C:[4,5.6,'%'],CREA:[0.7,1.3,'mg/dL'],UREIA:[15,45,'mg/dL'],COL:[0,190,'mg/dL'],TGO:[0,40,'U/L'],TSH:[0.4,4.5,'µUI/mL'],VITD:[30,100,'ng/mL'],HB:[13.5,17.5,'g/dL']};
const numRes=v=>parseFloat(String(v).replace(/[^\d,.-]/g,'').replace(',','.'));
function foraDaFaixa(ex,v){const f=FAIXA[ex];const n=numRes(v);if(!f||isNaN(n))return false;return n<f[0]||n>f[1]}
function dgAbrir(i){const d=DIGIT[i]||DIGIT[0];const e=EX[d.ex];const f=FAIXA[d.ex];
 openModal(`${mh('Registrar digitação · '+e.n)}<div class="mb" data-prot="${d.prot}"><div class="at-found"><h4>${esc(d.pac)} · <span class="mono">${d.cod}</span></h4><div>${e.m} · ${d.urg?'URGENTE, prazo '+d.prazo:'rotina, prazo '+d.prazo}${d.sit==='recusado'?' · <b style="color:var(--err)">recusado: '+d.motivo+'</b>':''} · <a href="#" onclick="event.preventDefault();historicoPaciente('${d.prot}','digitacao')">histórico do paciente (F2)</a></div></div>
<div class="formgrid">${d.ex==='EAS'?`<div class="field"><label>Cor</label><select class="in"><option>Amarelo claro</option><option>Amarelo</option><option>Âmbar</option></select></div><div class="field"><label>Leucócitos (sedimento) ${info('Dicionário de resultados: Ausentes, Raros, Numerosos, com texto padrão.')}</label><select class="in"><option>Ausentes</option><option>Raros</option><option>Numerosos</option></select></div><div class="field"><label>Nitrito</label><select class="in"><option>Negativo</option><option>Positivo</option></select></div>`:`<div class="field"><label>${e.n} <span class="req">*</span></label><div class="row"><input class="in" id="dgVal" value="${d.ex==='K'?'6,9':d.ex==='GLI'?'94':d.ex==='TSH'?'2,1':'6,1'}" style="max-width:140px" oninput="dgCheck(this.value,'${d.ex}')"><span>${f?f[2]:''}</span></div><span class="msg" id="dgMsg">Faixa: ${f?f[0]+' a '+f[1]:'—'}${d.ex==='K'?' · crítico < 2,5 ou > 6,0':d.ex==='GLI'?' · absurdo > 2.000':''}</span></div><div class="field"><label>Observação ${info('Do cadastro de Observações (busca por tipo e texto) ou texto livre.')}</label><input class="in" placeholder="Opcional"></div>`}</div>
${d.ex==='K'?'<div class="alert err"><span><b>Valor crítico (6,9 mmol/L).</b> Vai para a conferência marcado como crítico, fora do Liberar Sem Crítica, e dispara o aviso ao médico com confirmação de leitura.</span></div>':''}
<label class="check"><input type="checkbox">Adicionar imagem (até 3, com legenda)</label>
${(()=>{const ci=CONF.findIndex(x=>x.prot===d.prot&&x.ex===d.ex);const cref=ci>=0?CONF[ci]:{cod:d.cod,pac:d.pac,prot:d.prot,ex:d.ex,v:'',ref:'',al:'',orig:'',hist:[['14/10',d.ex==='GLI'?'88':'5,9'],['02/08',d.ex==='GLI'?'95':'5,7'],['12/03',d.ex==='GLI'?'91':'5,6'],['20/11/25',d.ex==='GLI'?'97':'5,8']]};const idx=reg(cref);return `<h4 style="margin-top:8px">Histórico deste exame ${info('Só resultados deste laboratório. Clique numa data para ver aquele resultado e os outros exames do dia.')}</h4>${histHtml(cref,idx)}<h4>Outros resultados deste paciente</h4>${outrosDoPaciente(cref,'digitacao')}`})()}
<div class="row" style="margin-top:12px;gap:6px"><button class="btn sm ghost" onclick="openModal(modalRecoleta())" ${tipAttr('Pedir nova amostra','Sugere a recoleta com motivo; o Dr. confirma antes de o paciente ser avisado.')}>Pedir nova amostra</button><button class="btn sm ghost" onclick="closeModal();toast('Amostra recusada com motivo: volta ao recebimento e abre recoleta sugerida','warn')" ${tipAttr('Recusar amostra','Hemólise, volume, tubo errado: a amostra inteira volta com motivo.')}>Recusar amostra</button><button class="btn sm ghost" onclick="toast('Observação do cadastro adicionada ao exame')">Observação do cadastro</button><span class="tl" style="margin-left:auto">Quem digita não libera: assinar é só do Dr.</span></div></div>
<div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn sec" onclick="closeModal();toast('Salvo parcialmente: só o que mudou')">Salvar parcialmente</button><button class="btn" onclick="closeModal();retorno('ok','Digitação salva','Resultado em D (digitado), aguardando a conferência do Dr. Quem digita não libera.')">Salvar digitação</button></div>`);setTimeout(()=>{const v=$('#dgVal');if(v)dgCheck(v.value,d.ex)},0)}
function dgCheck(v,ex){const n=numRes(v);const m=$('#dgMsg'),inp=$('#dgVal');if(!m)return;const f=FAIXA[ex];if(ex==='GLI'&&n>2000){m.textContent='Valor absurdo: digite de novo para confirmar';m.style.color='var(--err)';if(inp)inp.classList.add('fora');return}
 if(f&&!isNaN(n)&&(n<f[0]||n>f[1])){m.textContent='Fora da referência ('+f[0]+' a '+f[1]+'): vai para a conferência com alerta';m.style.color='var(--err)';if(inp)inp.classList.add('fora')}else{m.textContent='Faixa: '+(f?f[0]+' a '+f[1]:'—');m.style.color='';if(inp)inp.classList.remove('fora')}}
function dgLeitura(){openModal(`${mh('Leitura contínua · Bioquímica')}<div class="mb"><div class="inwrap">${LUPA}<input class="in" id="dgLeit" placeholder="Bipe o tubo, o código do exame no mapa ou unidade + protocolo"></div><div class="bip-log" id="dgLeitLog"></div><div class="alert info"><span>Cada tubo lido mostra só os exames manuais pendentes dele nesta bancada; se for um só, abre direto. Unidade + protocolo abre o paciente inteiro. Avisa amostra não recebida e exame já com resultado.</span></div></div><div class="mf"><button class="btn" onclick="closeModal()">Fechar</button></div>`);
 bipAuto($('#dgLeit'),c=>{const l=amostrasDe(c);if(!l.length){bipLog('dgLeitLog',`<span style="color:var(--err);font-weight:800">✕</span> ${c.cod}: não recebido nesta unidade`);return}if(c.tipo==='tubo'){bipLog('dgLeitLog',`<span class="ok">✓</span> ${c.cod} · ${esc(l[0].n)} · ${l[0].ex.join(', ')} · aberto para digitar`)}else{bipLog('dgLeitLog',`<span class="ok">✓</span> ${c.cod} · ${esc(l[0].n)} · ${l.length} tubos, ${l.reduce((s,a)=>s+a.ex.length,0)} exames · paciente aberto`);setTimeout(()=>historicoPaciente(c.cod,'digitacao'),200)}})}
/* Bipagem da tela: tubo → abre a digitação dele; protocolo → abre o paciente com todos os exames */
function dgBipagem(){bipAuto($('#dgBip'),c=>{const l=amostrasDe(c);if(!l.length){bipLog('dgLog',`<span style="color:var(--err);font-weight:800">✕</span> ${c.cod}: nenhuma amostra recebida com este código`);toast('Código não encontrado: confira a unidade e o protocolo','err');return}
 if(c.tipo==='tubo'){const i=DIGIT.findIndex(d=>d.cod===c.cod&&d.sit!=='recusado');bipLog('dgLog',`<span class="ok">✓</span> tubo ${c.cod} · ${esc(l[0].n)} · ${l[0].ex.join(', ')}`);if(i>=0)dgAbrir(i);else toast('Tubo '+c.cod+': exames vão para o aparelho ou já têm resultado','warn')}
 else{bipLog('dgLog',`<span class="ok">✓</span> protocolo ${c.cod} · ${esc(l[0].n)} · ${l.length} tubos, ${l.reduce((s,a)=>s+a.ex.length,0)} exames`);historicoPaciente(c.cod,'digitacao')}})}
GUIDES.digitacao=['Bipe o tubo (abre só ele) ou digite unidade + protocolo (abre o paciente inteiro, com todos os exames). O campo limpa sozinho para o próximo.','Digite: número e unidade separados; valor fora da faixa fica vermelho; absurdo pede nova digitação; crítico já sai marcado. F2 abre o histórico.','Salvar parcialmente guarda só o que mudou. Quem digita não libera: o resultado vai para a conferência do Dr.'];
