function cfAlarme(i){const c=CONF[i],a=c.alarme||{cod:'Flag do aparelho',sig:'Sem descrição cadastrada para este alarme.',faz:'Conferir antes de liberar.'};openModal(`${mh('Alarme do aparelho · '+c.orig.split(' · ')[0])}<div class="mb">${kvs([['Tubo',`<span class="mono">${c.cod}</span>`],['Exame',EX[c.ex].n+' · '+c.v],['Alarme',`<b>${a.cod}</b>`],['O que significa',a.sig],['O que fazer',a.faz]])}<p class="tl" style="margin-top:10px">A descrição de cada alarme vem do cadastro do aparelho (manual do fabricante) e pode ser completada pelo laboratório. ${info('Cadastros → Aparelhos → Alarmes: código, significado e conduta.')}</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn" onclick="closeModal();cfAbrir(${i})">Conferir</button></div>`)}
