function histHtml(c,i){const h=c.hist||[];if(!h.length)return '<p class="tl">Sem resultados anteriores neste laboratório.</p>';const f=FAIXA[c.ex==='HEMO'?'HB':c.ex];
 return `<div class="hist-lista">${h.slice(0,3).map(([d,v],j)=>`<span class="badge neutral" onclick="resultadoAntigo(${i},${j})" ${tipAttr(d,'Abre este resultado e os outros exames daquele dia.')}>${d} · ${v}</span>`).join('')}${h.length>3?`<button type="button" class="vermais" onclick="histCompleto(${i})">ver mais (${h.length-3})</button>`:''}</div>${graficoHist(h.slice(0,5),f,numRes(c.v))}`}
function histCompleto(i){const c=REG[i];const f=FAIXA[c.ex==='HEMO'?'HB':c.ex];openModal(`${mh('Histórico · '+EX[c.ex].n+' · '+esc(c.pac))}<div class="mb">${graficoHist(c.hist,f,numRes(c.v))}${tabela(['Data','Resultado','Referência',''],[['hoje',c.v,c.ref,-1]].concat(c.hist.map(([d,v],j)=>[d,v+(f?' '+f[2]:''),c.ref,j])).map(([d,v,ref,j])=>`<tr class="clk" ${j>=0?`onclick="resultadoAntigo(${i},${j})"`:''}>${td('Data',d)}${td('Resultado',`<b class="${f&&(numRes(v)<f[0]||numRes(v)>f[1])?'fora':''}">${v}</b>${f?setaHtml(dirFaixa(numRes(v),f[0],f[1])):''}`)}${td('Referência',ref)}${td('',j>=0?'<button class="btn sm ghost">Ver o dia</button>':'<span class="badge info">a conferir</span>')}</tr>`))}<p class="tl" style="margin-top:8px">Só resultados deste laboratório (P1).</p></div><div class="mf"><button class="btn" onclick="closeModal()">Fechar</button></div>`,'wide')}
